                          color: armed ? Colors.black : Colors.white70,
                        ),
                      ),
                    ],
                  ),
                ),
                // The "string" the tab is being pulled out on.
                Container(width: 2, height: stem, color: accent),
              ],
            ),
          ),
        );
      },
    );
  }
}

