/// Flutter's stock [HorizontalDragGestureRecognizer] accepts the gesture arena
/// as soon as |dx| crosses the touch slop, *without* looking at dy. Put one
/// above a vertical [Scrollable] and a diagonal flick becomes a coin toss:
/// whichever axis happens to cross slop on the earlier pointer-move event wins.
/// That is the "doesn't capture my gestures well" failure mode.
///
/// This subclass watches the accumulated delta and self-rejects the moment the
/// gesture reads as vertical, handing the arena to the scrollable cleanly and
/// early. It never makes itself *greedier* than the default — it only ever
/// declines — so it cannot steal a scroll.
class DirectionalHorizontalDragRecognizer extends HorizontalDragGestureRecognizer {
  DirectionalHorizontalDragRecognizer({
    super.debugOwner,
    this.verticalBailout = 8.0,
    this.dominanceRatio = 1.2,
  });

  /// How far the finger must travel vertically before we consider bailing out.
  final double verticalBailout;

  /// How much taller than wide the travel must be to count as "vertical".
  final double dominanceRatio;

  final Map<int, Offset> _travel = <int, Offset>{};

  @override
  void addAllowedPointer(PointerDownEvent event) {
    _travel[event.pointer] = Offset.zero;
    super.addAllowedPointer(event);
  }

  @override
  void handleEvent(PointerEvent event) {
    if (event is PointerMoveEvent) {
      final Offset total = (_travel[event.pointer] ?? Offset.zero) + event.delta;
      _travel[event.pointer] = total;
      gestureDebug.axis.value =
          '${total.dx.toStringAsFixed(0)},${total.dy.toStringAsFixed(0)}';
      final bool verticalish = total.dy.abs() > verticalBailout &&
          total.dy.abs() > total.dx.abs() * dominanceRatio;
      if (verticalish) {
        _travel.remove(event.pointer);
        // Concede the arena. The scrollable below us takes over for good.
        resolve(GestureDisposition.rejected);
        return;
      }
    }
    super.handleEvent(event);
  }

  @override
  void didStopTrackingLastPointer(int pointer) {
    _travel.remove(pointer);
    super.didStopTrackingLastPointer(pointer);
  }

  @override
  String get debugDescription => 'directional horizontal drag';
}

