import 'package:flutter/gestures.dart';
import 'package:flutter/material.dart';
import 'package:flutter_test/flutter_test.dart';

import 'package:gesture_lab/gestures.dart';

Widget harness(Widget child, List<String> log) {
  return MaterialApp(
    home: Scaffold(
      body: RawGestureDetector(
        behavior: HitTestBehavior.translucent,
        gestures: <Type, GestureRecognizerFactory>{
          DirectionalHorizontalDragRecognizer:
              GestureRecognizerFactoryWithHandlers<
                  DirectionalHorizontalDragRecognizer>(
            () => DirectionalHorizontalDragRecognizer(),
            (DirectionalHorizontalDragRecognizer r) {
              r
                ..onStart = (_) => log.add('start')
                ..onUpdate = (_) => log.add('update')
                ..onEnd = (_) => log.add('end')
                ..onCancel = () => log.add('cancel');
            },
          ),
        },
        child: child,
      ),
    ),
  );
}

Future<List<String>> swipe(WidgetTester tester, Widget child) async {
  final List<String> log = <String>[];
  await tester.pumpWidget(harness(child, log));
  await tester.pumpAndSettle();
  final TestGesture g = await tester.startGesture(const Offset(400, 300));
  for (int i = 0; i < 8; i++) {
    await g.moveBy(const Offset(30, 0));
    await tester.pump(const Duration(milliseconds: 16));
  }
  await g.up();
  await tester.pumpAndSettle();
  return log;
}

void main() {
  testWidgets('a: plain container', (WidgetTester tester) async {
    debugPrint('A => ${await swipe(tester, const ColoredBox(color: Colors.red))}');
  });

  testWidgets('b: scroll view', (WidgetTester tester) async {
    debugPrint('B => ${await swipe(tester, SingleChildScrollView(
      physics: const AlwaysScrollableScrollPhysics(parent: BouncingScrollPhysics()),
      child: const SizedBox(height: 2000),
    ))}');
  });

  testWidgets('c: bare text field', (WidgetTester tester) async {
    debugPrint('C => ${await swipe(tester, const Center(
      child: SizedBox(height: 400, child: TextField(maxLines: null)),
    ))}');
  });

  testWidgets('d: scroll view + text field', (WidgetTester tester) async {
    debugPrint('D => ${await swipe(tester, SingleChildScrollView(
      physics: const AlwaysScrollableScrollPhysics(parent: BouncingScrollPhysics()),
      child: const TextField(
        maxLines: null,
        scrollPhysics: NeverScrollableScrollPhysics(),
      ),
    ))}');
  });
}

