Widget harness(Widget child, List<String> log) {
  return MaterialApp(
    home: Scaffold(
      body: SizedBox.expand(
        child: RawGestureDetector(
          behavior: HitTestBehavior.translucent,
          gestures: <Type, GestureRecognizerFactory>{
            DirectionalHorizontalDragRecognizer:
                GestureRecognizerFactoryWithHandlers<
                    DirectionalHorizontalDragRecognizer>(
              () => DirectionalHorizontalDragRecognizer(),
              (DirectionalHorizontalDragRecognizer r) {
                r
                  ..onStart = (DragStartDetails _) { log.add('start'); }
                  ..onUpdate = (DragUpdateDetails _) { log.add('update'); }
                  ..onEnd = (DragEndDetails _) { log.add('end'); }
                  ..onCancel = () { log.add('cancel'); };
              },
            ),
          },
          child: Stack(fit: StackFit.expand, children: <Widget>[child]),
        ),
      ),
    ),
  );
}

Future<List<String>> swipe(WidgetTester tester, Widget child) async {
  final List<String> log = <String>[];
  await tester.pumpWidget(harness(child, log));
  await tester.pumpAndSettle();
  final TestGesture g = await tester.startGesture(const Offset(400, 300));
  for (int i = 0; i < 8; i++) {
    await g.moveBy(const Offset(30, 0));
    await tester.pump(const Duration(milliseconds: 16));
  }
  await g.up();
  await tester.pumpAndSettle();
  return log;
}

Widget scroller({bool autofocus = false}) => SingleChildScrollView(
      physics:
          const AlwaysScrollableScrollPhysics(parent: BouncingScrollPhysics()),
      child: TextField(
        autofocus: autofocus,
        maxLines: null,
        scrollPhysics: const NeverScrollableScrollPhysics(),
      ),
    );

void main() {
  testWidgets('e: scroller + autofocus', (WidgetTester tester) async {
    debugPrint('E => ${await swipe(tester, scroller(autofocus: true))}');
  });

  testWidgets('f: scroller + tap wrapper', (WidgetTester tester) async {
    debugPrint('F => ${await swipe(tester, GestureDetector(
      behavior: HitTestBehavior.translucent,
      onTap: () {},
      child: scroller(),
    ))}');
  });

  testWidgets('g: scroller + minHeight constraint', (WidgetTester tester) async {
    debugPrint('G => ${await swipe(tester, LayoutBuilder(
      builder: (BuildContext ctx, BoxConstraints c) => SingleChildScrollView(
        physics: const AlwaysScrollableScrollPhysics(
            parent: BouncingScrollPhysics()),
        child: ConstrainedBox(
          constraints: BoxConstraints(minHeight: c.maxHeight),
          child: const TextField(
            maxLines: null,
            scrollPhysics: NeverScrollableScrollPhysics(),
          ),
        ),
      ),
    ))}');
  });

  testWidgets('h: the real CapturePage', (WidgetTester tester) async {
    debugPrint('H => ${await swipe(tester, CapturePage(
      note: NoteModel(1),
      live: true,
      onPullCommit: () {},
    ))}');
  });
}

