// A TextField quietly installs a
// TapAndHorizontalDragGestureRecognizer for caret
// dragging, and it sits *deeper* in the hit-test path
// than the shell's swipe recognizer. On a fast flick a
// single pointer move can clear both thresholds at
// once, and the deeper one is dispatched first — so the
// field silently ate every swipe that started on text.
//
// gestureSettings is the supported lever for this:
// recognizers read their touch slop from the ambient
// MediaQuery, so raising it *only here* means the field
// needs a deliberate 44px drag while the shell still
// commits at 12. Not a race any more — an ordering.
// Taps, long-press and selection handles are untouched.
MediaQuery(
  data: media.copyWith(
    gestureSettings: const DeviceGestureSettings(
      touchSlop: 44,
    ),
  ),
  child: TextField(
    controller: widget.note.text,
    focusNode: widget.note.focus,
    autofocus: widget.live,
    maxLines: null,
    // Let the outer scroll view own every vertical drag.
    scrollPhysics: const NeverScrollableScrollPhysics(),
    keyboardAppearance: Brightness.dark,
    cursorColor: const Color(0xFF7AA2F7),
    style: const TextStyle(
      fontSize: 19,
      height: 1.5,
      color: Color(0xFFE8E8EC),
    ),
    decoration: InputDecoration.collapsed(
      hintText: 'Start typing…',
      hintStyle: TextStyle(
        color: Colors.white.withValues(alpha: 0.22),
      ),
    ),
  ),
),

