import 'package:flutter/gestures.dart';
import 'package:flutter/material.dart';
import 'package:flutter_test/flutter_test.dart';

import 'package:gesture_lab/capture_page.dart';
import 'package:gesture_lab/main.dart';

void main() {
  testWidgets('arena trace', (WidgetTester tester) async {
    await tester.pumpWidget(const GestureLabApp());
    await tester.pumpAndSettle();

    final Finder field = find.byType(TextField).first;
    debugPrintGestureArenaDiagnostics = true;
    final TestGesture g = await tester.startGesture(tester.getCenter(field));
    for (int i = 0; i < 4; i++) {
      await g.moveBy(const Offset(30, 0));
      await tester.pump(const Duration(milliseconds: 16));
    }
    await g.up();
    await tester.pumpAndSettle();
    debugPrintGestureArenaDiagnostics = false;

    debugPrint('>>> capture x = '
        '${tester.getTopLeft(find.byType(CapturePage).last).dx}');
  });
}

