8	/// Drags in small steps so the gesture recognizers see a realistic stream of
9	/// pointer moves, and leaves the finger *down* so the caller decides when the
10	/// release happens.
11	///
12	/// The timestamps matter: TestGesture.moveBy stamps every event at t=0 by
13	/// default, which makes VelocityTracker report zero and silently skips every
14	/// fling path in the app.
15	Future<TestGesture> dragInSteps(
16	  WidgetTester tester,
17	  Offset from,
18	  Offset step, {
19	  int count = 12,
20	  Duration interval = const Duration(milliseconds: 16),
21	}) async {
22	  Duration clock = Duration.zero;
23	  final TestGesture gesture = await tester.startGesture(from);
24	  for (int i = 0; i < count; i++) {
25	    clock += interval;
26	    await gesture.moveBy(step, timeStamp: clock);
27	    await tester.pump(interval);
28	  }
29	  return gesture;
30	}
